```elixir
defmodule KANActor do
  use GenServer

  defstruct [:id, :state, :neighbors, :weights]

  def start_link(id, initial_state) do
    GenServer.start_link(__MODULE__, {id, initial_state}, name: via_tuple(id))
  end

  defp via_tuple(id) do
    {:via, Registry, {KANRegistry, id}}
  end

  def init({id, initial_state}) do
    state = %__MODULE__{
      id: id,
      state: initial_state,
      neighbors: [],
      weights: %{}
    }
    {:ok, state}
  end

  def handle_call({:forward, input}, _from, state) do
    output = compute_activation(input, state.weights)
    {:reply, output, state}
  end

  def handle_call({:add_neighbor, neighbor_id, weight}, _from, state) do
    new_neighbors = [neighbor_id | state.neighbors]
    new_weights = Map.put(state.weights, neighbor_id, weight)
    new_state = %{state | neighbors: new_neighbors, weights: new_weights}
    {:reply, :ok, new_state}
  end

  def handle_call({:get_state}, _from, state) do
    {:reply, state.state, state}
  end

  def handle_cast({:update_state, new_state}, state) do
    {:noreply, %{state | state: new_state}}
  end

  def handle_cast({:update_weight, neighbor_id, new_weight}, state) do
    new_weights = Map.put(state.weights, neighbor_id, new_weight)
    {:noreply, %{state | weights: new_weights}}
  end

  def handle_cast({:broadcast, message}, state) do
    Enum.each(state.neighbors, fn neighbor_id ->
      GenServer.cast(via_tuple(neighbor_id), {:receive_message, message})
    end)
    {:noreply, state}
  end

  def handle_cast({:receive_message, message}, state) do
    new_state = process_message(message, state)
    {:noreply, new_state}
  end

  defp compute_activation(input, weights) do
    weights
    |> Map.values()
    |> Enum.zip(input)
    |> Enum.map(fn {w, x} -> w * x end)
    |> Enum.sum()
    |> apply_nonlinearity()
  end

  defp apply_nonlinearity(x) do
    :math.tanh(x)
  end

  defp process_message(message, state) do
    case message do
      {:data, data} ->
        %{state | state: data}
      {:gradient, grad} ->
        updated_weights = update_weights(state.weights, grad)
        %{state | weights: updated_weights}
      _ ->
        state
    end
  end

  defp update_weights(weights, gradient) do
    learning_rate = 0.01
    Map.new(weights, fn {k, v} ->
      grad_val = Map.get(gradient, k, 0.0)
      {k, v - learning_rate * grad_val}
    end)
  end

  def forward(actor_id, input) do
    GenServer.call(via_tuple(actor_id), {:forward, input})
  end

  def add_neighbor(actor_id, neighbor_id, weight) do
    GenServer.call(via_tuple(actor_id), {:add_neighbor, neighbor_id, weight})
  end

  def get_state(actor_id) do
    GenServer.call(via_tuple(actor_id), {:get_state})
  end

  def update_state(actor_id, new_state) do
    GenServer.cast(via_tuple(actor_id), {:update_state, new_state})
  end

  def update_weight(actor_id, neighbor_id, new_weight) do
    GenServer.cast(via_tuple(actor_id), {:update_weight, neighbor_id, new_weight})
  end

  def broadcast(actor_id, message) do
    GenServer.cast(via_tuple(actor_id), {:broadcast, message})
  end
end

defmodule KANNetwork do
  def start_network(num_actors) do
    {:ok, _} = Registry.start_link(keys: :unique, name: KANRegistry)

    actors = for i <- 0..(num_actors - 1) do
      {:ok, _pid} = KANActor.start_link(i, :rand.uniform())
      i
    end

    Enum.each(actors, fn actor_id ->
      neighbors = get_random_neighbors(actor_id, actors, 3)
      Enum.each(neighbors, fn neighbor_id ->
        weight = :rand.uniform() * 2.0 - 1.0
        KANActor.add_neighbor(actor_id, neighbor_id, weight)
      end)
    end)

    actors
  end

  defp get_random_neighbors(actor_id, all_actors, count) do
    all_actors
    |> Enum.reject(fn id -> id == actor_id end)
    |> Enum.take_random(count)
  end

  def forward_pass(actors, input_data) do
    Enum.map(actors, fn actor_id ->
      KANActor.forward(actor_id, input_data)
    end)
  end

  def synchronize_network(actors) do
    Enum.each(actors, fn actor_id ->
      state = KANActor.get_state(actor_id)
      KANActor.broadcast(actor_id, {:sync, state})
    end)
  end
end
