    var i: USize = 0
    while i < _neurons.size() do
      var j: USize = 0
      while j < _neurons.size() do
        if i != j then
          try
            let weight = (learning_rate - 0.5) * 2.0
            _neurons(i)?.add_neighbor(_neurons(j)?, weight)
