import gleam/list
import gleam/float
import gleam/int
import gleam/result
import gleam/dict.{type Dict}

pub type KANLayer {
  KANLayer(
    input_dim: Int,
    output_dim: Int,
    grid_size: Int,
    spline_order: Int,
    weights: List(List(Float)),
    grid_points: List(Float),
    control_points: List(List(Float)),
  )
}

pub type AdaptiveConfig {
  AdaptiveConfig(
    learning_rate: Float,
    momentum: Float,
    weight_decay: Float,
    clip_threshold: Float,
  )
}

pub fn create_layer(
  input_dim: Int,
  output_dim: Int,
  grid_size: Int,
  spline_order: Int,
) -> KANLayer {
  let weights = initialize_weights(input_dim, output_dim)
  let grid_points = create_grid(grid_size)
  let control_points = initialize_control_points(output_dim, grid_size)
  KANLayer(input_dim, output_dim, grid_size, spline_order, weights, grid_points, control_points)
}

fn initialize_weights(input_dim: Int, output_dim: Int) -> List(List(Float)) {
  let scale = 1.0 /. int.to_float(input_dim) |> float.square_root
  list.range(0, output_dim - 1)
  |> list.map(fn(_) {
    list.range(0, input_dim - 1)
    |> list.map(fn(_) { random_normal(0.0, scale) })
  })
}

fn random_normal(mean: Float, std: Float) -> Float {
  let u1 = float.random()
  let u2 = float.random()
  let z = float.square_root(-2.0 *. float_log(u1)) *. float_cos(2.0 *. pi() *. u2)
  mean +. std *. z
}

fn float_log(x: Float) -> Float {
  case x >. 0.0 {
    True -> do_log(x)
    False -> 0.0
  }
}

fn do_log(x: Float) -> Float {
  let iterations = 100
  let y = x -. 1.0
  list.range(1, iterations)
  |> list.fold(0.0, fn(acc, n) {
    let term = float.power(y, int.to_float(n)) /. int.to_float(n)
    let sign = case n % 2 {
      0 -> -1.0
      _ -> 1.0
    }
    acc +. sign *. term
  })
}

fn float_cos(x: Float) -> Float {
  let x_normalized = x -. float.floor(x /. {2.0 *. pi()}) *. 2.0 *. pi()
  taylor_cos(x_normalized, 10)
}

fn taylor_cos(x: Float, terms: Int) -> Float {
  list.range(0, terms - 1)
  |> list.fold(0.0, fn(acc, n) {
    let power = 2 * n
    let sign = case n % 2 {
      0 -> 1.0
      _ -> -1.0
    }
    let term = sign *. float.power(x, int.to_float(power)) /. int.to_float(factorial(power))
    acc +. term
  })
}

fn factorial(n: Int) -> Int {
  case n <= 1 {
    True -> 1
    False -> n * factorial(n - 1)
  }
}

fn pi() -> Float {
  3.141592653589793
}

fn create_grid(size: Int) -> List(Float) {
  list.range(0, size - 1)
  |> list.map(fn(i) { int.to_float(i) /. int.to_float(size - 1) })
}

fn initialize_control_points(output_dim: Int, grid_size: Int) -> List(List(Float)) {
  list.range(0, output_dim - 1)
  |> list.map(fn(_) {
    list.range(0, grid_size - 1)
    |> list.map(fn(_) { random_normal(0.0, 0.1) })
  })
}

pub fn forward(layer: KANLayer, input: List(Float)) -> List(Float) {
  list.range(0, layer.output_dim - 1)
  |> list.map(fn(i) {
    let weights_row = result.unwrap(list.at(layer.weights, i), [])
    let control_pts = result.unwrap(list.at(layer.control_points, i), [])

    let linear_combination = list.zip(weights_row, input)
      |> list.map(fn(pair) { pair.0 *. pair.1 })
      |> list.fold(0.0, float.add)

    evaluate_spline(linear_combination, layer.grid_points, control_pts, layer.spline_order)
  })
}

fn evaluate_spline(x: Float, grid: List(Float), control_points: List(Float), order: Int) -> Float {
  let n = list.length(grid)
  let clamped_x = float.max(0.0, float.min(1.0, x))

  let index = find_interval(clamped_x, grid)
  let t = local_parameter(clamped_x, grid, index)

  compute_basis_functions(t, order)
  |> list.zip(list.drop(control_points, index))
  |> list.take(order + 1)
  |> list.fold(0.0, fn(acc, pair) { acc +. pair.0 *. pair.1 })
}

fn find_interval(x: Float, grid: List(Float)) -> Int {
  list.index_fold(grid, 0, fn(idx, _, val) {
    case val <=. x {
      True -> idx
      False -> idx
    }
  })
}

fn local_parameter(x: Float, grid: List(Float), index: Int) -> Float {
  let start = result.unwrap(list.at(grid, index), 0.0)
  let end = result.unwrap(list.at(grid, index + 1), 1.0)
  case end -. start >. 0.0 {
    True -> {x -. start} /. {end -. start}
    False -> 0.0
  }
}

fn compute_basis_functions(t: Float, order: Int) -> List(Float) {
  case order {
    3 -> cubic_basis(t)
    2 -> quadratic_basis(t)
    1 -> linear_basis(t)
    _ -> [1.0]
  }
}

fn cubic_basis(t: Float) -> List(Float) {
  let t2 = t *. t
  let t3 = t2 *. t
  let one_minus_t = 1.0 -. t
  let one_minus_t2 = one_minus_t *. one_minus_t
  let one_minus_t3 = one_minus_t2 *. one_minus_t

  [
    one_minus_t3,
    3.0 *. t *. one_minus_t2,
    3.0 *. t2 *. one_minus_t,
    t3,
  ]
}

fn quadratic_basis(t: Float) -> List(Float) {
  let t2 = t *. t
  let one_minus_t = 1.0 -. t
  let one_minus_t2 = one_minus_t *. one_minus_t

  [one_minus_t2, 2.0 *. t *. one_minus_t, t2]
}

fn linear_basis(t: Float) -> List(Float) {
  [1.0 -. t, t]
}

pub fn backward(
  layer: KANLayer,
  input: List(Float),
  grad_output: List(Float),
  config: AdaptiveConfig,
) -> KANLayer {
  let updated_weights = update_weights(layer, input, grad_output, config)
  let updated_control_points = update_control_points(layer, input, grad_output, config)

  KANLayer(
    ..layer,
    weights: updated_weights,
    control_points: updated_control_points,
  )
}

fn update_weights(
  layer: KANLayer,
  input: List(Float),
  grad_output: List(Float),
  config: AdaptiveConfig,
) -> List(List(Float)) {
  list.index_map(layer.weights, fn(i, weight_row) {
    let grad_out = result.unwrap(list.at(grad_output, i), 0.0)
    list.map(weight_row, fn(w) {
      let gradient = compute_weight_gradient(w, input, grad_out)
      let clipped_grad = clip_gradient(gradient, config.clip_threshold)
      w -. config.learning_rate *. clipped_grad -. config.weight_decay *. w
    })
  })
}

fn compute_weight_gradient(weight: Float, input: List(Float), grad_out: Float) -> Float {
  list.fold(input, 0.0, fn(acc, x) { acc +. x *. grad_out })
}

fn clip_gradient(grad: Float, threshold: Float) -> Float {
  case float.absolute_value(grad) >. threshold {
    True -> float.sign(grad) *. threshold
    False -> grad
  }
}

fn update_control_points(
  layer: KANLayer,
  input: List(Float),
  grad_output: List(Float),
  config: AdaptiveConfig,
) -> List(List(Float)) {
  list.index_map(layer.control_points, fn(i, control_row) {
    let grad_out = result.unwrap(list.at(grad_output, i), 0.0)
    list.map(control_row, fn(cp) {
      let gradient = grad_out *. 0.1
      cp -. config.learning_rate *. gradient
    })
  })
}

pub fn adaptive_spline_refinement(layer: KANLayer, error_threshold: Float) -> KANLayer {
  let new_grid_size = layer.grid_size + 1
  let new_grid = create_grid(new_grid_size)
  let new_control_points = refine_control_points(layer.control_points, new_grid_size)

  KANLayer(
    ..layer,
    grid_size: new_grid_size,
    grid_points: new_grid,
    control_points: new_control_points,
  )
}

fn refine_control_points(old_points: List(List(Float)), new_size: Int) -> List(List(Float)) {
  list.map(old_points, fn(row) {
    interpolate_control_points(row, new_size)
  })
}

fn interpolate_control_points(points: List(Float), new_size: Int) -> List(Float) {
  let old_size = list.length(points)
  list.range(0, new_size - 1)
  |> list.map(fn(i) {
    let ratio = int.to_float(i) /. int.to_float(new_size - 1)
    let old_index = ratio *. int.to_float(old_size - 1)
    let idx = float.floor(old_index) |> float.truncate
    let t = old_index -. int.to_float(idx)

    let p1 = result.unwrap(list.at(points, idx), 0.0)
    let p2 = result.unwrap(list.at(points, int.min(idx + 1, old_size - 1)), 0.0)

    p1 *. {1.0 -. t} +. p2 *. t
  })
}
