import gleam/list
import gleam/int
import gleam/result

pub type Batch(a) {
  Batch(data: List(a), size: Int)
}

pub type BatchConfig {
  BatchConfig(batch_size: Int, drop_last: Bool, shuffle: Bool)
}

pub fn create_batches(data: List(a), config: BatchConfig) -> List(Batch(a)) {
  let processed_data = case config.shuffle {
    True -> shuffle_list(data)
    False -> data
  }

  chunk_data(processed_data, config.batch_size, config.drop_last)
}

fn chunk_data(data: List(a), batch_size: Int, drop_last: Bool) -> List(Batch(a)) {
  let total_size = list.length(data)
  let num_full_batches = total_size / batch_size
  let remainder = total_size % batch_size

  let full_batches = list.range(0, num_full_batches - 1)
    |> list.map(fn(i) {
      let start = i * batch_size
      let batch_data = list.drop(data, start) |> list.take(batch_size)
      Batch(data: batch_data, size: batch_size)
    })

  case drop_last, remainder {
    False, r if r > 0 -> {
      let last_batch_data = list.drop(data, num_full_batches * batch_size)
      let last_batch = Batch(data: last_batch_data, size: remainder)
      list.append(full_batches, [last_batch])
    }
    _, _ -> full_batches
  }
}

fn shuffle_list(data: List(a)) -> List(a) {
  let indexed = list.index_map(data, fn(i, item) { #(i, item) })
  let shuffled = list.sort(indexed, fn(a, b) {
    let rand_a = pseudo_random(a.0)
    let rand_b = pseudo_random(b.0)
    int.compare(rand_a, rand_b)
  })
  list.map(shuffled, fn(pair) { pair.1 })
}

fn pseudo_random(seed: Int) -> Int {
  let a = 1103515245
  let c = 12345
  let m = 2147483648
  {a * seed + c} % m
}

pub fn collate_batch(batch: Batch(List(Float))) -> List(List(Float)) {
  batch.data
}

pub fn pad_batch(batch: Batch(List(a)), pad_value: a, target_length: Int) -> Batch(List(a)) {
  let padded_data = list.map(batch.data, fn(sequence) {
    let current_length = list.length(sequence)
    case current_length < target_length {
      True -> {
        let padding_needed = target_length - current_length
        let padding = list.repeat(pad_value, padding_needed)
        list.append(sequence, padding)
      }
      False -> list.take(sequence, target_length)
    }
  })

  Batch(data: padded_data, size: batch.size)
}

pub fn batch_to_list(batch: Batch(a)) -> List(a) {
  batch.data
}

pub fn map_batch(batch: Batch(a), f: fn(a) -> b) -> Batch(b) {
