}

pub fn filter_batch(batch: Batch(a), predicate: fn(a) -> Bool) -> Batch(a) {
  let filtered = list.filter(batch.data, predicate)
  Batch(data: filtered, size: list.length(filtered))
}

pub fn concatenate_batches(batches: List(Batch(a))) -> List(a) {
  list.flat_map(batches, fn(batch) { batch.data })
}

pub fn batch_statistics(batch: Batch(Float)) -> #(Float, Float, Float) {
  let sum = list.fold(batch.data, 0.0, fn(acc, x) { acc +. x })
  let count = int.to_float(batch.size)
  let mean = sum /. count

  let variance = list.fold(batch.data, 0.0, fn(acc, x) {
    let diff = x -. mean
    acc +. diff *. diff
  }) /. count

  let min_val = list.fold(batch.data, 99999999.0, fn(acc, x) {
    case x <. acc {
      True -> x
      False -> acc
    }
  })

  #(mean, variance, min_val)
}

pub fn normalize_batch(batch: Batch(Float)) -> Batch(Float) {
  let #(mean, variance, _) = batch_statistics(batch)
  let std_dev = float_sqrt(variance)

  let normalized_data = list.map(batch.data, fn(x) {
    case std_dev >. 0.0 {
      True -> {x -. mean} /. std_dev
      False -> 0.0
    }
  })

  Batch(data: normalized_data, size: batch.size)
}

fn float_sqrt(x: Float) -> Float {
  case x <=. 0.0 {
    True -> 0.0
    False -> newton_sqrt(x, x /. 2.0, 10)
  }
}

fn newton_sqrt(x: Float, guess: Float, iterations: Int) -> Float {
  case iterations {
    0 -> guess
    _ -> {
      let new_guess = {guess +. x /. guess} /. 2.0
      newton_sqrt(x, new_guess, iterations - 1)
    }
  }
}

pub fn split_batch(batch: Batch(a), ratio: Float) -> #(Batch(a), Batch(a)) {
  let split_point = float.round(int.to_float(batch.size) *. ratio)
  let first_part = list.take(batch.data, split_point)
  let second_part = list.drop(batch.data, split_point)

  #(
    Batch(data: first_part, size: list.length(first_part)),
    Batch(data: second_part, size: list.length(second_part)),
  )
}

pub fn dynamic_batching(
  data: List(a),
  max_batch_size: Int,
  size_fn: fn(a) -> Int,
  max_tokens: Int,
) -> List(Batch(a)) {
  dynamic_batch_helper(data, max_batch_size, size_fn, max_tokens, [], [])
}

fn dynamic_batch_helper(
  remaining: List(a),
  max_batch_size: Int,
  size_fn: fn(a) -> Int,
  max_tokens: Int,
  current_batch: List(a),
  accumulated_batches: List(Batch(a)),
) -> List(Batch(a)) {
  case remaining {
    [] -> {
      case list.is_empty(current_batch) {
        True -> list.reverse(accumulated_batches)
        False -> {
          let final_batch = Batch(data: list.reverse(current_batch), size: list.length(current_batch))
          list.reverse([final_batch, ..accumulated_batches])
        }
      }
    }
    [item, ..rest] -> {
      let item_size = size_fn(item)
      let current_size = list.length(current_batch)
      let current_tokens = list.fold(current_batch, 0, fn(acc, x) { acc + size_fn(x) })

      case current_size >= max_batch_size || current_tokens + item_size > max_tokens {
        True -> {
          let batch = Batch(data: list.reverse(current_batch), size: current_size)
          dynamic_batch_helper(remaining, max_batch_size, size_fn, max_tokens, [], [batch, ..accumulated_batches])
        }
        False -> {
          dynamic_batch_helper(rest, max_batch_size, size_fn, max_tokens, [item, ..current_batch], accumulated_batches)
        }
      }
    }
  }
}
