  CheckpointManager(
    checkpoints: [],
    max_checkpoints: max_checkpoints,
    save_frequency: save_frequency,
    best_checkpoint: None,
  )
}

pub fn save_checkpoint(
  manager: CheckpointManager,
  epoch: Int,
  step: Int,
  loss: Float,
  metrics: Dict(String, Float),
  model_state: ModelState,
  optimizer_state: OptimizerState,
) -> CheckpointManager {
  let timestamp = get_timestamp()
  let checkpoint_id = generate_checkpoint_id(epoch, step)

  let checkpoint = Checkpoint(
    id: checkpoint_id,
    epoch: epoch,
    step: step,
    loss: loss,
    metrics: metrics,
    model_state: model_state,
    optimizer_state: optimizer_state,
    timestamp: timestamp,
  )

  let updated_checkpoints = [checkpoint, ..manager.checkpoints]
  let pruned_checkpoints = prune_checkpoints(updated_checkpoints, manager.max_checkpoints)
  let updated_best = update_best_checkpoint(manager.best_checkpoint, checkpoint)

  CheckpointManager(
    ..manager,
    checkpoints: pruned_checkpoints,
    best_checkpoint: updated_best,
  )
}

