fn update_best_checkpoint(
  current_best: Option(Checkpoint),
  new_checkpoint: Checkpoint,
) -> Option(Checkpoint) {
  case current_best {
    None -> Some(new_checkpoint)
    Some(best) -> {
      case new_checkpoint.loss <. best.loss {
        True -> Some(new_checkpoint)
        False -> Some(best)
