pub fn calculate_autoscaling(
  deployment: Deployment,
  current_cpu_usage: Float,
) -> Int {
  case deployment.config.scaling_policy {
    AutoScaling(min, max, target_cpu) -> {
      let scale_factor = current_cpu_usage /. target_cpu
      let desired_replicas = float.round(int.to_float(deployment.active_replicas) *. scale_factor)
      clamp(desired_replicas, min, max)
    }
    FixedReplicas(count) -> count
  }
}

pub fn canary_deployment(
  current: Deployment,
  canary: Deployment,
  traffic_percentage: Float,
) -> #(Deployment, Deployment) {
