  let canary_replicas = float.round(int.to_float(total_replicas) *. traffic_percentage)
  let current_replicas = total_replicas - canary_replicas

  #(
    Deployment(..current, active_replicas: current_replicas),
    Deployment(..canary, active_replicas: canary_replicas),
  )
}

pub fn blue_green_deployment(
