      Deployment(..green, active_replicas: green.config.replicas, status: Running),
    )
    False -> #(
      Deployment(..blue, active_replicas: blue.config.replicas, status: Running),
      Deployment(..green, active_replicas: 0, status: Pending),
    )
  }
}

