import gleam/list
import gleam/int
import gleam/float
import gleam/result
import gleam/dict.{type Dict}

pub type Worker {
  Worker(
    id: Int,
    rank: Int,
    world_size: Int,
    local_batch_size: Int,
    gradients: List(List(Float)),
  )
}

pub type DistributedConfig {
  DistributedConfig(
    num_workers: Int,
    backend: String,
    gradient_accumulation_steps: Int,
    use_mixed_precision: Bool,
    distributed_strategy: Strategy,
  )
}

pub type Strategy {
  DataParallel
  ModelParallel
  PipelineParallel
  ZeROOptimization(stage: Int)
}

pub type AllReduceOperation {
  Sum
  Average
  Max
  Min
}

pub fn create_worker(
  id: Int,
  rank: Int,
  world_size: Int,
  batch_size: Int,
) -> Worker {
  Worker(
    id: id,
    rank: rank,
    world_size: world_size,
    local_batch_size: batch_size / world_size,
    gradients: [],
  )
}

pub fn all_reduce(
  workers: List(Worker),
  operation: AllReduceOperation,
) -> List(Worker) {
  let all_gradients = list.map(workers, fn(w) { w.gradients })
  let reduced_gradients = reduce_gradients(all_gradients, operation)

  list.map(workers, fn(w) {
    Worker(..w, gradients: reduced_gradients)
  })
}

fn reduce_gradients(
  all_gradients: List(List(List(Float))),
  operation: AllReduceOperation,
) -> List(List(Float)) {
  case list.first(all_gradients) {
    Error(_) -> []
    Ok(first) -> {
      list.index_map(first, fn(layer_idx, _) {
        let layer_gradients = list.filter_map(all_gradients, fn(worker_grads) {
          list.at(worker_grads, layer_idx)
        })
        reduce_layer(layer_gradients, operation)
      })
    }
  }
}

fn reduce_layer(
  layer_gradients: List(List(Float)),
  operation: AllReduceOperation,
) -> List(Float) {
  case list.first(layer_gradients) {
    Error(_) -> []
    Ok(first) -> {
      list.index_map(first, fn(i, _) {
        let values = list.filter_map(layer_gradients, fn(grad) { list.at(grad, i) })
        reduce_values(values, operation)
      })
    }
  }
}

fn reduce_values(values: List(Float), operation: AllReduceOperation) -> Float {
  case operation {
    Sum -> list.fold(values, 0.0, float.add)
    Average -> {
      let sum = list.fold(values, 0.0, float.add)
      let count = list.length(values)
      case count > 0 {
        True -> sum /. int.to_float(count)
        False -> 0.0
      }
    }
    Max -> list.fold(values, -999999.0, float.max)
    Min -> list.fold(values, 999999.0, float.min)
  }
}

pub fn broadcast(
  source_worker: Worker,
  target_workers: List(Worker),
) -> List(Worker) {
  list.map(target_workers, fn(w) {
    Worker(..w, gradients: source_worker.gradients)
  })
}

pub fn scatter(
  data: List(List(Float)),
  workers: List(Worker),
) -> List(Worker) {
  let chunks = chunk_data(data, list.length(workers))
  list.zip(workers, chunks)
  |> list.map(fn(pair) {
    Worker(..pair.0, gradients: [pair.1])
  })
}

fn chunk_data(data: List(a), num_chunks: Int) -> List(List(a)) {
  let chunk_size = list.length(data) / num_chunks
  list.range(0, num_chunks - 1)
  |> list.map(fn(i) {
    list.drop(data, i * chunk_size)
    |> list.take(chunk_size)
  })
}

pub fn gather(workers: List(Worker), root_rank: Int) -> List(List(Float)) {
  list.flat_map(workers, fn(w) { w.gradients })
}

pub fn all_gather(workers: List(Worker)) -> List(Worker) {
  let all_gradients = list.flat_map(workers, fn(w) { w.gradients })
  list.map(workers, fn(w) {
    Worker(..w, gradients: [all_gradients])
  })
}

pub fn reduce_scatter(
  workers: List(Worker),
  operation: AllReduceOperation,
) -> List(Worker) {
  let reduced = all_reduce(workers, operation)
  let all_grads = case list.first(reduced) {
    Ok(w) -> w.gradients
    Error(_) -> []
  }

  let chunks = chunk_data(list.flatten(all_grads), list.length(workers))
  list.zip(reduced, chunks)
  |> list.map(fn(pair) {
    Worker(..pair.0, gradients: [pair.1])
  })
}

pub fn gradient_accumulation(
  worker: Worker,
  new_gradients: List(List(Float)),
  steps: Int,
) -> Worker {
  let accumulated = case list.length(worker.gradients) {
    0 -> new_gradients
    _ -> accumulate_gradients(worker.gradients, new_gradients)
  }

  Worker(..worker, gradients: accumulated)
}

fn accumulate_gradients(
  existing: List(List(Float)),
  new: List(List(Float)),
) -> List(List(Float)) {
  list.zip(existing, new)
  |> list.map(fn(pair) {
    list.zip(pair.0, pair.1)
    |> list.map(fn(grad_pair) { grad_pair.0 +. grad_pair.1 })
  })
}

pub fn zero_optimization_partition(
  model_params: List(List(Float)),
  workers: List(Worker),
  stage: Int,
) -> List(Worker) {
  case stage {
    1 -> partition_optimizer_states(workers, model_params)
    2 -> partition_gradients(workers, model_params)
    3 -> partition_parameters(workers, model_params)
    _ -> workers
  }
}

fn partition_optimizer_states(
  workers: List(Worker),
  params: List(List(Float)),
) -> List(Worker) {
  let chunks = chunk_data(params, list.length(workers))
  list.zip(workers, chunks)
  |> list.map(fn(pair) {
    Worker(..pair.0, gradients: [pair.1])
  })
}

fn partition_gradients(
  workers: List(Worker),
  params: List(List(Float)),
) -> List(Worker) {
  partition_optimizer_states(workers, params)
}

fn partition_parameters(
  workers: List(Worker),
  params: List(List(Float)),
) -> List(Worker) {
  partition_optimizer_states(workers, params)
}

pub fn ring_all_reduce(
  workers: List(Worker),
  operation: AllReduceOperation,
) -> List(Worker) {
  let num_workers = list.length(workers)
  ring_reduce_step(workers, operation, 0, num_workers)
}

fn ring_reduce_step(
  workers: List(Worker),
  operation: AllReduceOperation,
  step: Int,
  total_steps: Int,
) -> List(Worker) {
  case step >= total_steps {
    True -> workers
    False -> {
      let updated = list.index_map(workers, fn(i, worker) {
        let next_idx = {i + 1} % list.length(workers)
        let next_worker = result.unwrap(list.at(workers, next_idx), worker)
        let combined = accumulate_gradients(worker.gradients, next_worker.gradients)
        Worker(..worker, gradients: combined)
      })
      ring_reduce_step(updated, operation, step + 1, total_steps)
    }
  }
}

pub fn pipeline_parallel_forward(
  stages: List(List(List(Float))),
  micro_batches: Int,
) -> List(List(Float)) {
  list.fold(stages, [], fn(acc, stage) {
    case list.first(stage) {
      Ok(layer) -> [layer, ..acc]
      Error(_) -> acc
    }
  })
  |> list.reverse
}

