  let updated_world_size = list.length(workers) + 1
  let updated_workers = list.map(workers, fn(w) {
    Worker(..w, world_size: updated_world_size)
  })
  [Worker(..new_worker, world_size: updated_world_size), ..updated_workers]
}

pub fn elastic_training_remove_worker(
  workers: List(Worker),
  worker_id: Int,
) -> List(Worker) {
  let filtered = list.filter(workers, fn(w) { w.id != worker_id })
  let updated_world_size = list.length(filtered)
  list.map(filtered, fn(w) {
    Worker(..w, world_size: updated_world_size)
  })
}

pub fn compute_communication_cost(
  num_workers: Int,
  model_size_mb: Float,
  bandwidth_mbps: Float,
) -> Float {
  let total_data_transfer = model_size_mb *. int.to_float(num_workers - 1)
  total_data_transfer /. bandwidth_mbps
}
