import gleam/list
import gleam/int
import gleam/float
import gleam/result
import gleam/string

pub type EmbeddingMatrix {
  EmbeddingMatrix(
    vocab_size: Int,
    embedding_dim: Int,
    weights: List(List(Float)),
  )
}

pub type InitializationStrategy {
  Xavier
  He
  GlorotUniform
  GlorotNormal
  Orthogonal
  Uniform(min: Float, max: Float)
  Normal(mean: Float, std: Float)
}

pub fn initialize_embeddings(
  vocab_size: Int,
  embedding_dim: Int,
  strategy: InitializationStrategy,
) -> EmbeddingMatrix {
  let weights = create_weight_matrix(vocab_size, embedding_dim, strategy)
  EmbeddingMatrix(vocab_size: vocab_size, embedding_dim: embedding_dim, weights: weights)
}

fn create_weight_matrix(
  vocab_size: Int,
  embedding_dim: Int,
  strategy: InitializationStrategy,
) -> List(List(Float)) {
  list.range(0, vocab_size - 1)
  |> list.map(fn(i) { initialize_vector(embedding_dim, strategy, i) })
}

fn initialize_vector(
  dim: Int,
  strategy: InitializationStrategy,
  seed: Int,
) -> List(Float) {
  list.range(0, dim - 1)
  |> list.map(fn(j) { initialize_value(strategy, seed, j, dim) })
}

fn initialize_value(
  strategy: InitializationStrategy,
  seed: Int,
  index: Int,
  dim: Int,
) -> Float {
  case strategy {
    Xavier -> {
      let limit = float.square_root(6.0 /. int.to_float(dim))
      random_uniform(seed + index, 0.0 -. limit, limit)
    }
    He -> {
      let std = float.square_root(2.0 /. int.to_float(dim))
      random_normal(seed + index, 0.0, std)
    }
    GlorotUniform -> {
      let limit = float.square_root(6.0 /. int.to_float(dim * 2))
      random_uniform(seed + index, 0.0 -. limit, limit)
    }
    GlorotNormal -> {
      let std = float.square_root(2.0 /. int.to_float(dim * 2))
      random_normal(seed + index, 0.0, std)
    }
    Orthogonal -> {
      case index % 2 {
        0 -> 1.0
        _ -> 0.0
      }
    }
    Uniform(min, max) -> random_uniform(seed + index, min, max)
    Normal(mean, std) -> random_normal(seed + index, mean, std)
  }
}

fn random_uniform(seed: Int, min: Float, max: Float) -> Float {
  let normalized = pseudo_random_float(seed)
  min +. normalized *. {max -. min}
}

fn random_normal(seed: Int, mean: Float, std: Float) -> Float {
  let u1 = pseudo_random_float(seed)
  let u2 = pseudo_random_float(seed + 1)
  let z = float.square_root(-2.0 *. log_approx(u1)) *. cos_approx(2.0 *. pi() *. u2)
  mean +. std *. z
}

fn pseudo_random_float(seed: Int) -> Float {
  let a = 1103515245
  let c = 12345
  let m = 2147483648
  let result = {{a * seed} + c} % m
  int.to_float(result) /. int.to_float(m)
}

fn log_approx(x: Float) -> Float {
  case x >. 0.0 {
    True -> {
      let y = x -. 1.0
      y -. y *. y /. 2.0 +. y *. y *. y /. 3.0
    }
    False -> -10.0
  }
}

fn cos_approx(x: Float) -> Float {
  let x2 = x *. x
  1.0 -. x2 /. 2.0 +. x2 *. x2 /. 24.0
}

fn pi() -> Float {
  3.141592653589793
}

pub fn lookup_embedding(
  matrix: EmbeddingMatrix,
  token_id: Int,
) -> Result(List(Float), String) {
  case token_id >= 0 && token_id < matrix.vocab_size {
    True -> list.at(matrix.weights, token_id)
      |> result.replace_error("Token ID out of bounds")
    False -> Error("Invalid token ID")
  }
}

pub fn update_embedding(
  matrix: EmbeddingMatrix,
  token_id: Int,
  gradient: List(Float),
  learning_rate: Float,
) -> EmbeddingMatrix {
  let updated_weights = list.index_map(matrix.weights, fn(i, embedding) {
    case i == token_id {
      True -> list.zip(embedding, gradient)
        |> list.map(fn(pair) { pair.0 -. learning_rate *. pair.1 })
      False -> embedding
    }
  })

  EmbeddingMatrix(..matrix, weights: updated_weights)
}

pub fn normalize_embeddings(matrix: EmbeddingMatrix) -> EmbeddingMatrix {
  let normalized_weights = list.map(matrix.weights, fn(embedding) {
    let norm = compute_norm(embedding)
    case norm >. 0.0 {
      True -> list.map(embedding, fn(x) { x /. norm })
      False -> embedding
    }
  })

  EmbeddingMatrix(..matrix, weights: normalized_weights)
}

fn compute_norm(vector: List(Float)) -> Float {
  list.fold(vector, 0.0, fn(acc, x) { acc +. x *. x })
  |> float.square_root
}

pub fn cosine_similarity(vec1: List(Float), vec2: List(Float)) -> Float {
  let dot_product = list.zip(vec1, vec2)
    |> list.fold(0.0, fn(acc, pair) { acc +. pair.0 *. pair.1 })

  let norm1 = compute_norm(vec1)
  let norm2 = compute_norm(vec2)

  case norm1 >. 0.0 && norm2 >. 0.0 {
    True -> dot_product /. {norm1 *. norm2}
    False -> 0.0
  }
}

pub fn find_nearest_neighbors(
  matrix: EmbeddingMatrix,
  query_vector: List(Float),
  k: Int,
) -> List(#(Int, Float)) {
  list.index_map(matrix.weights, fn(i, embedding) {
    #(i, cosine_similarity(query_vector, embedding))
  })
  |> list.sort(fn(a, b) { float.compare(b.1, a.1) })
  |> list.take(k)
}

pub fn add_special_tokens(
  matrix: EmbeddingMatrix,
  num_special_tokens: Int,
  strategy: InitializationStrategy,
) -> EmbeddingMatrix {
  let special_embeddings = create_weight_matrix(
    num_special_tokens,
    matrix.embedding_dim,
    strategy,
  )

  EmbeddingMatrix(
    vocab_size: matrix.vocab_size + num_special_tokens,
    embedding_dim: matrix.embedding_dim,
    weights: list.append(special_embeddings, matrix.weights),
  )
}

pub fn freeze_embeddings(matrix: EmbeddingMatrix, freeze_mask: List(Bool)) -> EmbeddingMatrix {
  matrix
}

pub fn apply_dropout_to_embeddings(
  embeddings: List(Float),
  dropout_rate: Float,
  seed: Int,
) -> List(Float) {
  list.index_map(embeddings, fn(i, x) {
    case pseudo_random_float(seed + i) >. dropout_rate {
      True -> x /. {1.0 -. dropout_rate}
      False -> 0.0
    }
  })
}

pub fn compute_embedding_statistics(matrix: EmbeddingMatrix) -> #(Float, Float) {
  let all_values = list.flatten(matrix.weights)
  let sum = list.fold(all_values, 0.0, float.add)
  let count = list.length(all_values)
  let mean = sum /. int.to_float(count)

  let variance = list.fold(all_values, 0.0, fn(acc, x) {
    let diff = x -. mean
    acc +. diff *. diff
  }) /. int.to_float(count)

  #(mean, variance)
}
