    recall: recall,
    f1_score: f1_score,
    loss: 0.0,
    confusion_matrix: confusion_matrix,
  )
}

fn build_confusion_matrix(
  predictions: List(Prediction),
  num_classes: Int,
) -> List(List(Int)) {
  let empty_matrix = list.range(0, num_classes - 1)
    |> list.map(fn(_) { list.repeat(0, num_classes) })

  list.fold(predictions, empty_matrix, fn(matrix, pred) {
    increment_matrix_cell(matrix, pred.actual, pred.predicted)
  })
}

fn increment_matrix_cell(
  matrix: List(List(Int)),
  row: Int,
  col: Int,
) -> List(List(Int)) {
  list.index_map(matrix, fn(i, matrix_row) {
    case i == row {
      True -> list.index_map(matrix_row, fn(j, val) {
        case j == col {
          True -> val + 1
          False -> val
        }
      })
      False -> matrix_row
    }
  })
}

fn calculate_accuracy(predictions: List(Prediction)) -> Float {
  let correct = list.count(predictions, fn(pred) { pred.predicted == pred.actual })
  let total = list.length(predictions)
  case total > 0 {
    True -> int.to_float(correct) /. int.to_float(total)
    False -> 0.0
  }
}

fn calculate_precision(
  confusion_matrix: List(List(Int)),
  num_classes: Int,
) -> Float {
  let precisions = list.range(0, num_classes - 1)
    |> list.map(fn(class) {
      let true_positives = get_matrix_value(confusion_matrix, class, class)
      let predicted_positives = sum_column(confusion_matrix, class)
      case predicted_positives > 0 {
        True -> int.to_float(true_positives) /. int.to_float(predicted_positives)
        False -> 0.0
      }
    })

  let sum = list.fold(precisions, 0.0, float.add)
  sum /. int.to_float(num_classes)
}

fn calculate_recall(
  confusion_matrix: List(List(Int)),
  num_classes: Int,
) -> Float {
  let recalls = list.range(0, num_classes - 1)
    |> list.map(fn(class) {
      let true_positives = get_matrix_value(confusion_matrix, class, class)
      let actual_positives = sum_row(confusion_matrix, class)
      case actual_positives > 0 {
        True -> int.to_float(true_positives) /. int.to_float(actual_positives)
        False -> 0.0
      }
    })

  let sum = list.fold(recalls, 0.0, float.add)
  sum /. int.to_float(num_classes)
}

fn calculate_f1_score(precision: Float, recall: Float) -> Float {
  case precision +. recall >. 0.0 {
    True -> 2.0 *. precision *. recall /. {precision +. recall}
    False -> 0.0
  }
}

fn get_matrix_value(matrix: List(List(Int)), row: Int, col: Int) -> Int {
  list.at(matrix, row)
  |> result.then(fn(matrix_row) { list.at(matrix_row, col) })
  |> result.unwrap(0)
}

fn sum_row(matrix: List(List(Int)), row: Int) -> Int {
  list.at(matrix, row)
  |> result.unwrap([])
  |> list.fold(0, int.add)
}

fn sum_column(matrix: List(List(Int)), col: Int) -> Int {
  list.fold(matrix, 0, fn(acc, row) {
    acc + result.unwrap(list.at(row, col), 0)
  })
}

pub fn calculate_perplexity(cross_entropy_loss: Float) -> Float {
  float.power(2.718281828, cross_entropy_loss)
}

pub fn calculate_bleu_score(
  reference: List(String),
  candidate: List(String),
  max_n: Int,
) -> Float {
  let n_gram_scores = list.range(1, max_n)
    |> list.map(fn(n) {
      calculate_n_gram_precision(reference, candidate, n)
    })

  let geometric_mean = geometric_mean_list(n_gram_scores)
  let brevity_penalty = calculate_brevity_penalty(reference, candidate)

  brevity_penalty *. geometric_mean
}

fn calculate_n_gram_precision(
  reference: List(String),
  candidate: List(String),
  n: Int,
) -> Float {
  let ref_ngrams = extract_n_grams(reference, n)
  let cand_ngrams = extract_n_grams(candidate, n)

  let matches = count_matches(cand_ngrams, ref_ngrams)
  let total = list.length(cand_ngrams)

  case total > 0 {
    True -> int.to_float(matches) /. int.to_float(total)
    False -> 0.0
  }
}

fn extract_n_grams(tokens: List(String), n: Int) -> List(List(String)) {
  case list.length(tokens) < n {
    True -> []
    False -> {
      list.range(0, list.length(tokens) - n)
      |> list.map(fn(i) { list.drop(tokens, i) |> list.take(n) })
    }
  }
}

fn count_matches(cand_ngrams: List(List(String)), ref_ngrams: List(List(String))) -> Int {
  list.count(cand_ngrams, fn(cand_gram) {
    list.any(ref_ngrams, fn(ref_gram) { cand_gram == ref_gram })
  })
}

fn geometric_mean_list(values: List(Float)) -> Float {
  let product = list.fold(values, 1.0, float.multiply)
  let n = list.length(values)
  float.power(product, 1.0 /. int.to_float(n))
}

fn calculate_brevity_penalty(reference: List(String), candidate: List(String)) -> Float {
  let ref_len = list.length(reference)
  let cand_len = list.length(candidate)

  case cand_len >= ref_len {
    True -> 1.0
    False -> float.power(2.718281828, 1.0 -. int.to_float(ref_len) /. int.to_float(cand_len))
  }
}

pub fn calculate_rouge_l(reference: List(String), candidate: List(String)) -> Float {
  let lcs_length = longest_common_subsequence_length(reference, candidate)
  let ref_len = list.length(reference)
  let cand_len = list.length(candidate)

  case ref_len > 0 && cand_len > 0 {
    True -> {
      let recall = int.to_float(lcs_length) /. int.to_float(ref_len)
      let precision = int.to_float(lcs_length) /. int.to_float(cand_len)
      case recall +. precision >. 0.0 {
        True -> 2.0 *. recall *. precision /. {recall +. precision}
        False -> 0.0
      }
    }
    False -> 0.0
  }
}

fn longest_common_subsequence_length(seq1: List(String), seq2: List(String)) -> Int {
  let len1 = list.length(seq1)
  let len2 = list.length(seq2)

  case len1 == 0 || len2 == 0 {
    True -> 0
    False -> lcs_helper(seq1, seq2, len1, len2)
  }
}

fn lcs_helper(seq1: List(String), seq2: List(String), len1: Int, len2: Int) -> Int {
  case len1 == 0 || len2 == 0 {
    True -> 0
    False -> {
      let elem1 = result.unwrap(list.at(seq1, len1 - 1), "")
      let elem2 = result.unwrap(list.at(seq2, len2 - 1), "")

      case elem1 == elem2 {
        True -> 1 + lcs_helper(seq1, seq2, len1 - 1, len2 - 1)
        False -> {
          let option1 = lcs_helper(seq1, seq2, len1 - 1, len2)
          let option2 = lcs_helper(seq1, seq2, len1, len2 - 1)
          int.max(option1, option2)
        }
      }
    }
  }
}

pub fn calculate_mean_absolute_error(predictions: List(Float), targets: List(Float)) -> Float {
  let errors = list.zip(predictions, targets)
    |> list.map(fn(pair) { float.absolute_value(pair.0 -. pair.1) })

  let sum = list.fold(errors, 0.0, float.add)
  let count = list.length(errors)

  case count > 0 {
    True -> sum /. int.to_float(count)
    False -> 0.0
  }
}

pub fn calculate_mean_squared_error(predictions: List(Float), targets: List(Float)) -> Float {
  let errors = list.zip(predictions, targets)
    |> list.map(fn(pair) {
      let diff = pair.0 -. pair.1
      diff *. diff
    })

  let sum = list.fold(errors, 0.0, float.add)
  let count = list.length(errors)

  case count > 0 {
    True -> sum /. int.to_float(count)
    False -> 0.0
  }
}

pub fn calculate_r_squared(predictions: List(Float), targets: List(Float)) -> Float {
  let mean_target = list.fold(targets, 0.0, float.add) /. int.to_float(list.length(targets))

  let ss_res = list.zip(predictions, targets)
    |> list.fold(0.0, fn(acc, pair) {
      let diff = pair.1 -. pair.0
      acc +. diff *. diff
    })

  let ss_tot = list.fold(targets, 0.0, fn(acc, y) {
    let diff = y -. mean_target
    acc +. diff *. diff
  })

  case ss_tot >. 0.0 {
    True -> 1.0 -. ss_res /. ss_tot
    False -> 0.0
  }
}

pub fn calculate_auc_roc(
  predictions: List(Float),
  labels: List(Int),
) -> Float {
  let sorted_pairs = list.zip(predictions, labels)
    |> list.sort(fn(a, b) { float.compare(b.0, a.0) })

  let positives = list.count(labels, fn(l) { l == 1 })
  let negatives = list.count(labels, fn(l) { l == 0 })

  case positives > 0 && negatives > 0 {
    True -> {
      let auc = calculate_auc_helper(sorted_pairs, 0, 0, 0.0)
      auc /. int.to_float(positives * negatives)
    }
    False -> 0.0
  }
}

fn calculate_auc_helper(
  pairs: List(#(Float, Int)),
  true_positives: Int,
  false_positives: Int,
  auc: Float,
) -> Float {
  case pairs {
    [] -> auc
    [pair, ..rest] -> {
      case pair.1 {
        1 -> calculate_auc_helper(rest, true_positives + 1, false_positives, auc)
        _ -> calculate_auc_helper(rest, true_positives, false_positives + 1, auc +. int.to_float(true_positives))
      }
    }
  }
}

pub fn cross_validate(
  data: List(a),
  k_folds: Int,
  train_fn: fn(List(a)) -> b,
  eval_fn: fn(b, List(a)) -> Float,
) -> Float {
  let fold_size = list.length(data) / k_folds
  let scores = list.range(0, k_folds - 1)
    |> list.map(fn(i) {
      let validation_set = list.drop(data, i * fold_size) |> list.take(fold_size)
      let training_set = list.append(
        list.take(data, i * fold_size),
        list.drop(data, {i + 1} * fold_size),
      )

      let model = train_fn(training_set)
      eval_fn(model, validation_set)
    })

  let sum = list.fold(scores, 0.0, float.add)
  sum /. int.to_float(k_folds)
}
