pub fn create_fractal_kan(
  depth: Int,
  base_dim: Int,
  pattern: FractalPattern,
) -> FractalKAN {
  let scaling_factor = 1.0 /. float.square_root(int.to_float(depth))
  let root_layer = create_fractal_layer(0, depth, base_dim, pattern, scaling_factor)

  FractalKAN(
    depth: depth,
    base_dim: base_dim,
    scaling_factor: scaling_factor,
    layers: [root_layer],
