fn create_fractal_layer(
  current_level: Int,
  max_depth: Int,
  dimension: Int,
  pattern: FractalPattern,
  scaling: Float,
) -> FractalLayer {
  let weights = initialize_fractal_weights(dimension, pattern, current_level)

  let children = case current_level < max_depth {
    True -> {
      let num_children = calculate_branching_factor(pattern)
      let child_dim = calculate_child_dimension(dimension, num_children)

      list.range(0, num_children - 1)
      |> list.map(fn(_) {
        create_fractal_layer(current_level + 1, max_depth, child_dim, pattern, scaling)
      })
    }
    False -> []
  }

