fn forward_layer(
  layer: FractalLayer,
  input: List(Float),
  scaling: Float,
) -> List(Float) {
  let linear_output = matrix_vector_multiply(layer.weights, input)
  let activated = list.map(linear_output, fractal_activation)

  case list.is_empty(layer.child_layers) {
    True -> activated
    False -> {
      let child_outputs = list.map(layer.child_layers, fn(child) {
        forward_layer(child, activated, scaling)
      })

      aggregate_child_outputs(child_outputs, scaling)
    }
  }
}

fn matrix_vector_multiply(matrix: List(List(Float)), vector: List(Float)) -> List(Float) {
  list.map(matrix, fn(row) {
    list.zip(row, vector)
    |> list.map(fn(pair) { pair.0 *. pair.1 })
    |> list.fold(0.0, float.add)
  })
}

