fn aggregate_child_outputs(outputs: List(List(Float)), scaling: Float) -> List(Float) {
  case list.first(outputs) {
    Error(_) -> []
    Ok(first) -> {
      list.index_map(first, fn(i, _) {
        list.fold(outputs, 0.0, fn(acc, output) {
          acc +. result.unwrap(list.at(output, i), 0.0) *. scaling
        })
      })
    }
  }
