pub fn compute_fractal_dimension(layer: FractalLayer) -> Float {
  let num_children = list.length(layer.child_layers)
  case num_children {
    0 -> 0.0
    _ -> {
      let scaling_ratio = int.to_float(layer.dimension) /. int.to_float(result.unwrap(list.first(layer.child_layers), layer).dimension)
      log_base(int.to_float(num_children), scaling_ratio)
    }
  }
}

fn log_base(base: Float, x: Float) -> Float {
  case base >. 0.0 && x >. 0.0 {
    True -> log_natural(x) /. log_natural(base)
    False -> 0.0
  }
}

fn log_natural(x: Float) -> Float {
  case x >. 0.0 {
    True -> {
      let y = x -. 1.0
      y -. y *. y /. 2.0 +. y *. y *. y /. 3.0 -. y *. y *. y *. y /. 4.0
    }
    False -> 0.0
  }
}

pub fn self_similar_regularization(layer: FractalLayer) -> Float {
  case list.is_empty(layer.child_layers) {
    True -> 0.0
    False -> {
      let parent_norm = frobenius_norm(layer.weights)
      let child_norms = list.map(layer.child_layers, fn(child) {
        frobenius_norm(child.weights)
      })

      let child_sum = list.fold(child_norms, 0.0, float.add)
      float.absolute_value(parent_norm -. child_sum /. int.to_float(list.length(child_norms)))
    }
  }
}

fn frobenius_norm(matrix: List(List(Float))) -> Float {
  list.fold(matrix, 0.0, fn(acc, row) {
    acc +. list.fold(row, 0.0, fn(acc2, x) { acc2 +. x *. x })
  })
  |> float.square_root
}

pub fn prune_fractal_layer(layer: FractalLayer, threshold: Float) -> FractalLayer {
  let pruned_weights = list.map(layer.weights, fn(row) {
    list.map(row, fn(w) {
      case float.absolute_value(w) <. threshold {
        True -> 0.0
        False -> w
      }
    })
  })

  let pruned_children = list.map(layer.child_layers, fn(child) {
    prune_fractal_layer(child, threshold)
  })

  FractalLayer(..layer, weights: pruned_weights, child_layers: pruned_children)
}
