    list.repeat(-1, negative),
  )
  GeometricSpace(dimension: dimension, signature: signature)
}

pub fn geometric_product(a: Multivector, b: Multivector) -> Multivector {
  let new_scalar = a.scalar *. b.scalar +. dot_product(a.vector, b.vector)

  let new_vector = list.zip(a.vector, b.vector)
    |> list.map(fn(pair) {
      a.scalar *. pair.1 +. b.scalar *. pair.0
    })

  let new_bivector = wedge_product_vectors(a.vector, b.vector)

  let new_trivector = []
  let new_pseudoscalar = 0.0

  Multivector(
    scalar: new_scalar,
    vector: new_vector,
    bivector: new_bivector,
    trivector: new_trivector,
    pseudoscalar: new_pseudoscalar,
  )
}

fn dot_product(v1: List(Float), v2: List(Float)) -> Float {
  list.zip(v1, v2)
  |> list.fold(0.0, fn(acc, pair) { acc +. pair.0 *. pair.1 })
}

fn wedge_product_vectors(v1: List(Float), v2: List(Float)) -> List(Float) {
  case list.length(v1) >= 2 && list.length(v2) >= 2 {
    True -> {
      let x1 = result.unwrap(list.at(v1, 0), 0.0)
      let y1 = result.unwrap(list.at(v1, 1), 0.0)
      let x2 = result.unwrap(list.at(v2, 0), 0.0)
      let y2 = result.unwrap(list.at(v2, 1), 0.0)
      [x1 *. y2 -. y1 *. x2]
    }
    False -> []
  }
}

pub fn inner_product(a: Multivector, b: Multivector) -> Float {
  a.scalar *. b.scalar +. dot_product(a.vector, b.vector)
}

pub fn outer_product(a: Multivector, b: Multivector) -> List(Float) {
  wedge_product_vectors(a.vector, b.vector)
}

pub fn reverse(mv: Multivector) -> Multivector {
  Multivector(
    scalar: mv.scalar,
    vector: mv.vector,
    bivector: list.map(mv.bivector, fn(x) { 0.0 -. x }),
    trivector: list.map(mv.trivector, fn(x) { 0.0 -. x }),
    pseudoscalar: 0.0 -. mv.pseudoscalar,
  )
}

pub fn grade_projection(mv: Multivector, grade: Int) -> Multivector {
  case grade {
    0 -> Multivector(mv.scalar, [], [], [], 0.0)
    1 -> Multivector(0.0, mv.vector, [], [], 0.0)
    2 -> Multivector(0.0, [], mv.bivector, [], 0.0)
    3 -> Multivector(0.0, [], [], mv.trivector, 0.0)
    _ -> Multivector(0.0, [], [], [], mv.pseudoscalar)
  }
}

pub fn magnitude(mv: Multivector) -> Float {
  let scalar_sq = mv.scalar *. mv.scalar
  let vector_sq = list.fold(mv.vector, 0.0, fn(acc, x) { acc +. x *. x })
  let bivector_sq = list.fold(mv.bivector, 0.0, fn(acc, x) { acc +. x *. x })
  let trivector_sq = list.fold(mv.trivector, 0.0, fn(acc, x) { acc +. x *. x })
  let pseudo_sq = mv.pseudoscalar *. mv.pseudoscalar

  float.square_root(scalar_sq +. vector_sq +. bivector_sq +. trivector_sq +. pseudo_sq)
}

pub fn normalize(mv: Multivector) -> Multivector {
  let mag = magnitude(mv)
  case mag >. 0.0 {
    True -> Multivector(
      scalar: mv.scalar /. mag,
      vector: list.map(mv.vector, fn(x) { x /. mag }),
      bivector: list.map(mv.bivector, fn(x) { x /. mag }),
      trivector: list.map(mv.trivector, fn(x) { x /. mag }),
      pseudoscalar: mv.pseudoscalar /. mag,
    )
    False -> mv
  }
}

pub fn create_rotor(angle: Float, plane: List(Float)) -> Rotor {
  let half_angle = angle /. 2.0
  let cos_half = cos_approx(half_angle)
  let sin_half = sin_approx(half_angle)

  let bivector = list.map(plane, fn(x) { x *. sin_half })

  Rotor(scalar: cos_half, bivector: bivector)
}

fn cos_approx(x: Float) -> Float {
  let x2 = x *. x
  1.0 -. x2 /. 2.0 +. x2 *. x2 /. 24.0
}

fn sin_approx(x: Float) -> Float {
  let x2 = x *. x
  x -. x *. x2 /. 6.0 +. x *. x2 *. x2 /. 120.0
}

pub fn apply_rotor(rotor: Rotor, vector: List(Float)) -> List(Float) {
  let mv = Multivector(0.0, vector, [], [], 0.0)
  let rotor_mv = Multivector(rotor.scalar, [], rotor.bivector, [], 0.0)
  let rotor_rev = reverse(rotor_mv)

  let rotated = geometric_product(rotor_mv, mv)
  let result = geometric_product(rotated, rotor_rev)

  result.vector
}

pub fn embed_text_geometric(
  text: String,
  dimension: Int,
) -> Multivector {
  let hash = string_hash(text)
  let norm_hash = int.to_float(hash) /. 2147483648.0

  let scalar = norm_hash
  let vector = list.range(0, dimension - 1)
    |> list.map(fn(i) {
      let val = int.to_float({hash + i * 1103515245} % 2147483648)
      val /. 2147483648.0
    })

  let bivector = []
  let trivector = []
  let pseudoscalar = 0.0

  normalize(Multivector(scalar, vector, bivector, trivector, pseudoscalar))
}

fn string_hash(s: String) -> Int {
  let bytes = string.to_utf_codepoints(s)
  list.fold(bytes, 5381, fn(hash, char) {
    {{hash * 33} + char} % 2147483648
  })
}

pub fn geometric_attention(
  query: Multivector,
  key: Multivector,
  value: Multivector,
) -> Multivector {
  let similarity = inner_product(query, key)
  let attention_weight = 1.0 /. {1.0 +. float.power(2.718281828, 0.0 -. similarity)}

  scale_multivector(value, attention_weight)
}

fn scale_multivector(mv: Multivector, scale: Float) -> Multivector {
  Multivector(
    scalar: mv.scalar *. scale,
    vector: list.map(mv.vector, fn(x) { x *. scale }),
    bivector: list.map(mv.bivector, fn(x) { x *. scale }),
    trivector: list.map(mv.trivector, fn(x) { x *. scale }),
    pseudoscalar: mv.pseudoscalar *. scale,
  )
}

pub fn clifford_convolution(
  input: List(Multivector),
  kernel: List(Multivector),
) -> List(Multivector) {
  let kernel_size = list.length(kernel)
  let input_size = list.length(input)

  list.range(0, input_size - kernel_size)
  |> list.map(fn(i) {
    let window = list.drop(input, i) |> list.take(kernel_size)
    list.zip(window, kernel)
    |> list.fold(Multivector(0.0, [], [], [], 0.0), fn(acc, pair) {
      add_multivectors(acc, geometric_product(pair.0, pair.1))
    })
  })
}

fn add_multivectors(a: Multivector, b: Multivector) -> Multivector {
  Multivector(
    scalar: a.scalar +. b.scalar,
    vector: list.zip(pad_list(a.vector, b.vector), pad_list(b.vector, a.vector))
      |> list.map(fn(pair) { pair.0 +. pair.1 }),
    bivector: list.zip(pad_list(a.bivector, b.bivector), pad_list(b.bivector, a.bivector))
      |> list.map(fn(pair) { pair.0 +. pair.1 }),
    trivector: list.zip(pad_list(a.trivector, b.trivector), pad_list(b.trivector, a.trivector))
      |> list.map(fn(pair) { pair.0 +. pair.1 }),
    pseudoscalar: a.pseudoscalar +. b.pseudoscalar,
  )
}

fn pad_list(list1: List(Float), list2: List(Float)) -> List(Float) {
  let len1 = list.length(list1)
  let len2 = list.length(list2)
  case len1 < len2 {
    True -> list.append(list1, list.repeat(0.0, len2 - len1))
    False -> list1
  }
}

pub fn dual(mv: Multivector) -> Multivector {
  Multivector(
    scalar: mv.pseudoscalar,
    vector: mv.trivector,
    bivector: [],
    trivector: mv.vector,
    pseudoscalar: mv.scalar,
  )
}

pub fn meet(a: Multivector, b: Multivector) -> Multivector {
  dual(geometric_product(dual(a), dual(b)))
}

pub fn join(a: Multivector, b: Multivector) -> Multivector {
  let outer = outer_product(a, b)
  Multivector(0.0, [], outer, [], 0.0)
}
