import gleam/list
import gleam/float
import gleam/int
import gleam/result

pub type HyperNetwork {
  HyperNetwork(
    meta_layers: List(MetaLayer),
    target_network_size: Int,
    embedding_dim: Int,
  )
}

pub type MetaLayer {
  MetaLayer(
    input_dim: Int,
    output_dim: Int,
    weights: List(List(Float)),
    biases: List(Float),
  )
}

pub type GeneratedWeights {
  GeneratedWeights(
    layer_weights: List(List(List(Float))),
    layer_biases: List(List(Float)),
  )
}

pub type HyperParams {
  HyperParams(
    context_vector: List(Float),
    task_embedding: List(Float),
  )
}

pub fn create_hypernetwork(
  meta_layers_config: List(#(Int, Int)),
  target_network_size: Int,
  embedding_dim: Int,
) -> HyperNetwork {
  let meta_layers = list.map(meta_layers_config, fn(config) {
    create_meta_layer(config.0, config.1)
  })

  HyperNetwork(
    meta_layers: meta_layers,
    target_network_size: target_network_size,
    embedding_dim: embedding_dim,
  )
}

fn create_meta_layer(input_dim: Int, output_dim: Int) -> MetaLayer {
  let scale = float.square_root(2.0 /. int.to_float(input_dim))
  let weights = list.range(0, output_dim - 1)
    |> list.map(fn(i) {
      list.range(0, input_dim - 1)
      |> list.map(fn(j) { random_normal(i * output_dim + j, 0.0, scale) })
    })

  let biases = list.repeat(0.0, output_dim)

  MetaLayer(
    input_dim: input_dim,
    output_dim: output_dim,
    weights: weights,
    biases: biases,
  )
}

fn random_normal(seed: Int, mean: Float, std: Float) -> Float {
  let u1 = pseudo_random_float(seed)
  let u2 = pseudo_random_float(seed + 1)
  let z = float.square_root(-2.0 *. log_approx(u1)) *. cos_approx(2.0 *. pi() *. u2)
  mean +. std *. z
}

fn pseudo_random_float(seed: Int) -> Float {
  let a = 1103515245
  let c = 12345
  let m = 2147483648
  let result = {{a * seed} + c} % m
  int.to_float(result) /. int.to_float(m)
}

fn log_approx(x: Float) -> Float {
  case x >. 0.0 {
    True -> {
      let y = x -. 1.0
      y -. y *. y /. 2.0 +. y *. y *. y /. 3.0
    }
    False -> -10.0
  }
}

fn cos_approx(x: Float) -> Float {
  let x2 = x *. x
  1.0 -. x2 /. 2.0 +. x2 *. x2 /. 24.0
}

fn pi() -> Float {
  3.141592653589793
}

pub fn generate_weights(
  hypernetwork: HyperNetwork,
  hyper_params: HyperParams,
) -> GeneratedWeights {
  let combined_input = list.append(
    hyper_params.context_vector,
    hyper_params.task_embedding,
  )

  let meta_output = forward_hypernetwork(hypernetwork.meta_layers, combined_input)

  let layer_weights = partition_weights(
    meta_output,
    hypernetwork.target_network_size,
  )

  let layer_biases = partition_biases(
    meta_output,
    hypernetwork.target_network_size,
  )

  GeneratedWeights(layer_weights: layer_weights, layer_biases: layer_biases)
}

fn forward_hypernetwork(
  layers: List(MetaLayer),
  input: List(Float),
) -> List(Float) {
  list.fold(layers, input, fn(current_input, layer) {
    forward_meta_layer(layer, current_input)
  })
}

fn forward_meta_layer(layer: MetaLayer, input: List(Float)) -> List(Float) {
  list.index_map(layer.weights, fn(i, weight_row) {
    let linear = list.zip(weight_row, input)
      |> list.fold(0.0, fn(acc, pair) { acc +. pair.0 *. pair.1 })

    let bias = result.unwrap(list.at(layer.biases, i), 0.0)
    activation(linear +. bias)
  })
}

fn activation(x: Float) -> Float {
  case x >. 0.0 {
    True -> x
    False -> 0.01 *. x
  }
}

fn partition_weights(
  flat_weights: List(Float),
  num_layers: Int,
) -> List(List(List(Float))) {
  let weights_per_layer = list.length(flat_weights) / num_layers
  list.range(0, num_layers - 1)
  |> list.map(fn(layer_idx) {
    let layer_start = layer_idx * weights_per_layer
    let layer_flat = list.drop(flat_weights, layer_start)
      |> list.take(weights_per_layer)

    let matrix_size = float.square_root(int.to_float(list.length(layer_flat)))
      |> float.truncate

    chunk_into_matrix(layer_flat, matrix_size)
  })
}

fn chunk_into_matrix(flat: List(Float), size: Int) -> List(List(Float)) {
  case size > 0 {
    True -> {
      list.range(0, size - 1)
      |> list.map(fn(i) {
        list.drop(flat, i * size) |> list.take(size)
      })
    }
    False -> [[]]
  }
}

fn partition_biases(
  flat_weights: List(Float),
