  let biases_per_layer = list.length(flat_weights) / num_layers / 10
  list.range(0, num_layers - 1)
  |> list.map(fn(layer_idx) {
    list.drop(flat_weights, layer_idx * biases_per_layer)
    |> list.take(biases_per_layer)
