  let context_vector = compute_context_vector(task_data)
  let task_embedding = embed_task(task_data, hypernetwork.embedding_dim)

  HyperParams(context_vector: context_vector, task_embedding: task_embedding)
}

fn compute_context_vector(data: List(Float)) -> List(Float) {
  let mean = list.fold(data, 0.0, float.add) /. int.to_float(list.length(data))
  let variance = list.fold(data, 0.0, fn(acc, x) {
    let diff = x -. mean
    acc +. diff *. diff
  }) /. int.to_float(list.length(data))

  [mean, variance, list.fold(data, -999999.0, float.max), list.fold(data, 999999.0, float.min)]
}

fn embed_task(data: List(Float), embed_dim: Int) -> List(Float) {
  list.range(0, embed_dim - 1)
  |> list.map(fn(i) {
    let idx = i % list.length(data)
    result.unwrap(list.at(data, idx), 0.0)
  })
}

pub fn conditional_generation(
  hypernetwork: HyperNetwork,
  condition: List(Float),
  num_samples: Int,
