  list.range(0, num_samples - 1)
  |> list.map(fn(i) {
    let noisy_condition = add_noise(condition, 0.01, i)
    let hyper_params = HyperParams(
      context_vector: noisy_condition,
      task_embedding: embed_task(noisy_condition, hypernetwork.embedding_dim),
    )
    generate_weights(hypernetwork, hyper_params)
  })
}

fn add_noise(data: List(Float), noise_level: Float, seed: Int) -> List(Float) {
  list.index_map(data, fn(i, x) {
