  })
}

pub fn weight_sharing_regularization(
  generated_weights: List(GeneratedWeights),
) -> Float {
  case list.length(generated_weights) < 2 {
    True -> 0.0
    False -> {
      let first = result.unwrap(list.first(generated_weights), GeneratedWeights([], []))
      list.drop(generated_weights, 1)
      |> list.fold(0.0, fn(acc, weights) {
        acc +. compute_weight_distance(first, weights)
      })
    }
  }
}

fn compute_weight_distance(w1: GeneratedWeights, w2: GeneratedWeights) -> Float {
  let layer_distances = list.zip(w1.layer_weights, w2.layer_weights)
    |> list.map(fn(pair) {
      matrix_frobenius_distance(pair.0, pair.1)
    })

  list.fold(layer_distances, 0.0, float.add)
}

fn matrix_frobenius_distance(m1: List(List(Float)), m2: List(List(Float))) -> Float {
  list.zip(m1, m2)
  |> list.fold(0.0, fn(acc, row_pair) {
    let row_dist = list.zip(row_pair.0, row_pair.1)
      |> list.fold(0.0, fn(acc2, elem_pair) {
        let diff = elem_pair.0 -. elem_pair.1
        acc2 +. diff *. diff
      })
    acc +. row_dist
  })
  |> float.square_root
}

pub fn train_hypernetwork(
  hypernetwork: HyperNetwork,
  training_tasks: List(List(Float)),
  learning_rate: Float,
) -> HyperNetwork {
  let gradients = compute_meta_gradients(hypernetwork, training_tasks)
  update_hypernetwork_weights(hypernetwork, gradients, learning_rate)
}

fn compute_meta_gradients(
  hypernetwork: HyperNetwork,
  tasks: List(List(Float)),
) -> List(List(List(Float))) {
  list.map(hypernetwork.meta_layers, fn(layer) {
    list.map(layer.weights, fn(row) {
      list.map(row, fn(_) { 0.01 })
    })
  })
}

fn update_hypernetwork_weights(
  hypernetwork: HyperNetwork,
  gradients: List(List(List(Float))),
  lr: Float,
) -> HyperNetwork {
  let updated_layers = list.zip(hypernetwork.meta_layers, gradients)
    |> list.map(fn(pair) {
      let layer = pair.0
      let grad = pair.1

      let updated_weights = list.zip(layer.weights, grad)
        |> list.map(fn(weight_grad_pair) {
          list.zip(weight_grad_pair.0, weight_grad_pair.1)
          |> list.map(fn(w_g) { w_g.0 -. lr *. w_g.1 })
        })

      MetaLayer(..layer, weights: updated_weights)
    })

  HyperNetwork(..hypernetwork, meta_layers: updated_layers)
}

pub fn interpolate_networks(
  weights1: GeneratedWeights,
  weights2: GeneratedWeights,
  alpha: Float,
) -> GeneratedWeights {
  let interpolated_weights = list.zip(weights1.layer_weights, weights2.layer_weights)
    |> list.map(fn(layer_pair) {
      list.zip(layer_pair.0, layer_pair.1)
      |> list.map(fn(matrix_pair) {
        list.zip(matrix_pair.0, matrix_pair.1)
        |> list.map(fn(elem_pair) {
          alpha *. elem_pair.0 +. {1.0 -. alpha} *. elem_pair.1
        })
      })
    })

  let interpolated_biases = list.zip(weights1.layer_biases, weights2.layer_biases)
    |> list.map(fn(bias_pair) {
      list.zip(bias_pair.0, bias_pair.1)
      |> list.map(fn(elem_pair) {
        alpha *. elem_pair.0 +. {1.0 -. alpha} *. elem_pair.1
      })
    })

  GeneratedWeights(
    layer_weights: interpolated_weights,
    layer_biases: interpolated_biases,
  )
}
